const item = $input.first().json || {};
const workflow = item.workflow || item.workflowData || {};
const execution = item.execution || item.executionData || {};
const error = item.error || item.lastNodeExecuted || {};
const baseUrl = String($env.PUBLIC_N8N_BASE_URL || $env.N8N_EDITOR_BASE_URL || '').replace(/\/$/, '');
const workflowId = workflow.id || execution.workflowId || item.workflowId || 'unknown';
const workflowName = workflow.name || item.workflowName || 'Unknown workflow';
const executionId = execution.id || item.executionId || 'unknown';
const nodeName = error.node?.name || error.nodeName || item.lastNodeExecuted || 'unknown node';
const message = error.message || item.message || item.errorMessage || 'Unknown error';
const stack = error.stack || item.stack || '';
const responseBodyRaw = error.response?.body ?? error.cause?.response?.body ?? item.response?.body ?? item.body?.responseBody ?? item.responseBody ?? '';
const responseBody = typeof responseBodyRaw === 'string' ? responseBodyRaw : (responseBodyRaw ? JSON.stringify(responseBodyRaw) : '');
const responseBodyExcerpt = responseBody.length > 1200 ? `${responseBody.slice(0, 1200)}...` : responseBody;
const mode = execution.mode || item.mode || 'unknown';
const startedAt = execution.startedAt || item.startedAt || new Date().toISOString();
const executionUrl = baseUrl && workflowId !== 'unknown' && executionId !== 'unknown'
  ? `${baseUrl}/workflow/${workflowId}/executions/${executionId}`
  : '';
const dlqPath = $env.N8N_ERROR_DLQ_PATH || '/files/dlq/n8n-errors.jsonl';

const record = {
  timestamp: new Date().toISOString(),
  workflowId,
  workflowName,
  executionId,
  nodeName,
  mode,
  startedAt,
  message,
  responseBody: responseBodyExcerpt,
  executionUrl,
  stack
};

const text = [
  'n8n workflow failure',
  `Workflow: ${workflowName}`,
  `Node: ${nodeName}`,
  `Execution: ${executionId}`,
  `Mode: ${mode}`,
  `Started: ${startedAt}`,
  `Error: ${message}`,
  responseBodyExcerpt ? `Response body: ${responseBodyExcerpt}` : '',
  executionUrl ? `Open: ${executionUrl}` : ''
].filter(Boolean).join('\n');

const binaryData = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(record) + '\n'), 'error.jsonl', 'text/plain');

return [{
  json: {
    ...record,
    dlqPath,
    telegramText: text,
    chatId: $env.TELEGRAM_ERROR_CHAT_ID || $env.TELEGRAM_APPROVAL_CHAT_ID
  },
  binary: {
    data: binaryData
  }
}];
